const body = $input.first().json.body || $input.first().json;
const name = body.name || 'amigo(a)';
const service = body.service === 'mayoreo' ? 'Venta a Mayoreo' : 'Catering & Barra Móvil';
const notes = body.notes ? `\n📝 Detalles que nos compartiste: ${body.notes}` : '';
const rawPhone = String(body.phone || '').replace(/[^\d+]/g, '');
const toPhone = rawPhone.startsWith('+') ? rawPhone : `+${rawPhone}`;

const message = service === 'Venta a Mayoreo'
  ? `¡Hola ${name}! ☕🥐 Gracias por contactar a *Moulú Café* en Mexicali.\n\nRecibimos tu solicitud de *Venta a Mayoreo* (panadería artesanal, galletas y café de especialidad en grano).${notes}\n\nEn un momento te compartimos nuestro catálogo y precios por volumen.`
  : `¡Hola ${name}! ✨☕ Gracias por contactar a *Moulú Café* en Mexicali.\n\nRecibimos tu solicitud de *Catering & Barra Móvil* (Centinela, Salty Latte, Matcha Ceremonial y panadería).${notes}\n\n¿Para qué fecha y cuántas personas sería tu evento?`;

return [{ json: { name, toPhone, service, message } }];
